// beadmod-cym
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Filter, View } from '../types'
import {
  FILTERS,
  detail,
  parseSnapshot,
  summary,
  viewActivity,
  viewBoard,
  viewGraph,
  viewIssues,
  viewMemory,
  viewReady,
  viewStats,
  viewTree,
} from './model'
import type { Row, Tone, ViewOut } from './model'

const PANE = 'beads'
// beadmod-pe3
const VIEWS: { id: View; key: string; label: string }[] = [
  { id: 'board', key: 'b', label: 'Board' },
  { id: 'ready', key: 'r', label: 'Ready' },
  { id: 'issues', key: 'i', label: 'Issues' },
  { id: 'graph', key: 'g', label: 'Graph' },
  { id: 'tree', key: 't', label: 'Tree' },
  { id: 'activity', key: 'a', label: 'Activity' },
  { id: 'memory', key: 'm', label: 'Memory' },
  { id: 'stats', key: 's', label: 'Stats' },
]

const view = atom({ plugin: 'beadmod', key: 'view' } as const, 'board' as View)
const snapshot = atom({ plugin: 'beadmod', key: 'snap' } as const, null)
const selected = atom({ plugin: 'beadmod', key: 'selected' } as const, null)
const showClosed = atom({ plugin: 'beadmod', key: 'showClosed' } as const, false)
// beadmod-93m
const filter = atom({ plugin: 'beadmod', key: 'filter' } as const, 'all' as Filter)

const isView = (s: string): s is View => VIEWS.some(v => v.id === s)

const TONES: Record<Tone, { color?: string; dimColor?: boolean; weight?: 'bold' }> = {
  plain: {},
  dim: { dimColor: true },
  ok: { color: 'success' },
  warn: { color: 'warning' },
  bad: { color: 'error' },
  accent: { color: 'suggestion' },
  head: { weight: 'bold' },
}

const bd = async ($: EngineInterface, argv: string[]) => {
  const ran = await $.process.run(['bd', ...argv, '--json'], { timeoutMs: 20_000 })
  if (ran.exitCode !== 0) throw new Error(ran.stderr.trim() || ran.stdout.trim() || `bd exited ${ran.exitCode}`)

  return ran.stdout
}

let pending: Promise<void> | null = null

const refresh = ($: EngineInterface): Promise<void> => {
  pending ??= (async () => {
    try {
      // beadmod-93m
      const [list, ready, blocked, memories] = await Promise.all([
        bd($, ['list', '--all', '--limit', '0']),
        bd($, ['ready']),
        bd($, ['blocked']),
        bd($, ['memories']).catch(() => '{}'),
      ])
      const snap = parseSnapshot(list, ready, blocked, memories, await $.clock.now())
      await update($, snapshot, () => snap)
      $.ui.status(summary(snap))
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      await update($, snapshot, () => ({
        beads: [],
        memories: [],
        ready: [],
        blocked: {},
        at: 0,
        error: message,
      }))
      $.ui.status(undefined)
    }
  })().finally(() => {
    pending = null
  })

  return pending
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'beadview',
      description: 'Look at beads: /beadview [board|ready|graph|tree|stats]',
      argumentHint: '[board|ready|graph|tree|stats]',
    })
    void refresh($)

    return next(e)
  })

  on('command.run', { command: 'beadview' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg !== '' && !isView(arg)) {
      return { text: `Unknown view "${arg}". Views: ${VIEWS.map(v => v.id).join(', ')}.` }
    }
    if (isView(arg)) await update($, view, () => arg)
    await $.ui.open({ id: PANE, title: 'Beads', focus: true, closeOnEscape: true, rows: 22 })
    await refresh($)

    return { text: 'Beads pane opened.' }
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    if (/(^|[\s;&|(])bd\s/.test(e.command)) void refresh($)

    return ran
  })

  on('turn.complete', ($, e, next) => {
    void refresh($)

    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const width = Math.max(30, e.props.bodyColumns)
    const current = await read($, view)
    const snap = await read($, snapshot)
    const pick = await read($, selected)
    const isClosedShown = await read($, showClosed)
    const activeFilter = await read($, filter) // beadmod-93m

    const draw = (row: Row, key: string) => {
      const isPicked = row.id !== undefined && row.id === pick
      const parts = row.parts.map(p => (
        <Text {...TONES[p.tone ?? 'plain']} {...(isPicked ? { weight: 'bold' as const } : {})}>
          {p.t}
        </Text>
      ))
      if (row.id === undefined) return <Box key={key}>{parts}</Box>
      const id = row.id

      return (
        <Button
          key={key}
          plain
          onPress={() => update($, selected, cur => (cur === id ? null : id))}
        >
          {parts}
        </Button>
      )
    }
    const heading = (title: string, tone: Tone | undefined) => (
      <Text {...TONES[tone ?? 'head']} weight="bold">
        {title}
      </Text>
    )

    const tabs = (
      <Box gap={0}>
        {VIEWS.map(v => (
          // beadmod-760
          <Button
            key={`tab-${v.id}`}
            hotkey={v.key}
            variant={v.id === current ? 'primary' : 'secondary'}
            onPress={() => update($, view, () => v.id)}
          >
            {v.key}
          </Button>
        ))}
        <Button
          key="closed"
          hotkey="c"
          plain
          dimColor
          onPress={() => update($, showClosed, n => !n)}
        >
          {isClosedShown ? 'c: hide closed' : 'c: show closed'}
        </Button>
        {/* beadmod-93m */}
        {current === 'issues' && (
          <Button
            key="filter"
            hotkey="l"
            plain
            dimColor
            onPress={() =>
              update($, filter, cur => FILTERS[(FILTERS.indexOf(cur) + 1) % FILTERS.length] ?? 'all')
            }
          >
            l: filter
          </Button>
        )}
        <Button key="refresh" hotkey="f" plain dimColor onPress={() => refresh($)}>
          f: refresh
        </Button>
      </Box>
    )

    if (snap === null) {
      return (
        <Box flexDirection="column">
          {tabs}
          <Text dimColor>Loading beads…</Text>
        </Box>
      )
    }
    if (snap.error !== null) {
      return (
        <Box flexDirection="column">
          {tabs}
          <Text color="error">bd failed: {snap.error}</Text>
          <Text dimColor>Run this from a directory with a beads workspace (bd init).</Text>
        </Box>
      )
    }
    if (snap.beads.length === 0) {
      return (
        <Box flexDirection="column">
          {tabs}
          <Text dimColor>No beads here yet. Create one: bd create "title" -t task -p 2</Text>
        </Box>
      )
    }

    const out: ViewOut =
      current === 'board'
        ? viewBoard(snap, width)
        : current === 'ready'
          ? viewReady(snap, width)
          : current === 'graph'
            ? viewGraph(snap, width, isClosedShown)
            : current === 'tree'
              ? viewTree(snap, width, isClosedShown)
              : current === 'issues'
                ? viewIssues(snap, width, isClosedShown, activeFilter)
                : current === 'activity'
                  ? viewActivity(snap, width)
                  : current === 'memory'
                    ? viewMemory(snap, width)
                    : viewStats(snap, width)

    const body =
      out.layout === 'columns' ? (
        <Box gap={2}>
          {out.sections.map((s, i) => (
            <Box
              key={`col-${i}`}
              flexDirection="column"
              width={Math.floor((width - (out.sections.length - 1) * 2) / out.sections.length)}
            >
              {heading(s.title, s.tone)}
              {s.rows.map((r, j) => draw(r, `${r.id ?? 'x'}-${i}-${j}`))}
            </Box>
          ))}
        </Box>
      ) : (
        <Box flexDirection="column">
          {out.sections.map((s, i) => (
            <Box key={`sec-${i}`} flexDirection="column" marginBottom={1}>
              {heading(s.title, s.tone)}
              {s.rows.map((r, j) => draw(r, `${r.id ?? 'x'}-${i}-${j}`))}
            </Box>
          ))}
        </Box>
      )

    const focus = pick === null ? [] : detail(snap, pick, width - 2)

    return (
      <Box flexDirection="column">
        {tabs}
        {body}
        {out.note !== undefined && <Text dimColor>{out.note}</Text>}
        {focus.length > 0 && (
          <Box flexDirection="column" borderStyle="round" paddingX={1}>
            {focus.map((r, j) => draw(r, `d-${j}`))}
          </Box>
        )}
        {/* beadmod-pe3 */}
        <Text dimColor>
          {VIEWS.map(v => `${v.key} ${v.label.toLowerCase()}`).join(' · ')}
        </Text>
        <Text dimColor>Enter on a row for details · Esc to leave the pane</Text>
      </Box>
    )
  })
}

