// beadmod-cym
import type { Bead, Filter, Memory, Snapshot } from '../types'

export type Tone = 'plain' | 'dim' | 'ok' | 'warn' | 'bad' | 'accent' | 'head'
export type Part = { t: string; tone?: Tone }
export type Row = { id?: string; parts: Part[] }
export type Section = { title: string; tone?: Tone; rows: Row[] }
export type ViewOut = { layout: 'columns' | 'stack'; sections: Section[]; note?: string }

type State = 'ready' | 'in_progress' | 'blocked' | 'waiting' | 'closed'

const BLOCKING = ['blocks', 'conditional-blocks', 'waits-for']
const ICON: Record<State, string> = {
  ready: '○',
  in_progress: '◐',
  blocked: '●',
  waiting: '❄',
  closed: '✓',
}
const TONE: Record<State, Tone> = {
  ready: 'ok',
  in_progress: 'accent',
  blocked: 'bad',
  waiting: 'warn',
  closed: 'dim',
}
const DONE_LIMIT = 12
const DAY = 86_400_000

const asText = (v: unknown): string | null => (typeof v === 'string' && v !== '' ? v : null)

const parseJson = (text: string): unknown => {
  try {
    return JSON.parse(text)
  } catch {
    return null
  }
}

const toBead = (raw: Record<string, unknown>): Bead | null => {
  const id = asText(raw.id)
  if (id === null) return null
  const deps = (Array.isArray(raw.dependencies) ? raw.dependencies : []).flatMap(d => {
    const dep = d as Record<string, unknown>
    const to = asText(dep.depends_on_id) ?? asText(dep.id)
    const type = asText(dep.type) ?? asText(dep.dependency_type)
    return to !== null && type !== null ? [{ to, type }] : []
  })
  const parent = asText(raw.parent) ?? deps.find(d => d.type === 'parent-child')?.to ?? null

  return {
    id,
    title: asText(raw.title) ?? id,
    status: asText(raw.status) ?? 'open',
    priority: typeof raw.priority === 'number' ? raw.priority : 2,
    type: asText(raw.issue_type) ?? 'task',
    assignee: asText(raw.assignee),
    parent,
    description: asText(raw.description),
    createdAt: asText(raw.created_at),
    updatedAt: asText(raw.updated_at),
    closedAt: asText(raw.closed_at), // beadmod-93m
    deps,
  }
}

// beadmod-93m
export const parseMemories = (memText: string): Memory[] => {
  const raw = parseJson(memText)
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) return []

  return Object.entries(raw as Record<string, unknown>)
    .filter(([k, v]) => k !== 'schema_version' && typeof v === 'string')
    .map(([key, text]) => ({ key, text: text as string }))
    .sort((a, b) => a.key.localeCompare(b.key))
}

export const parseSnapshot = (
  listText: string,
  readyText: string,
  blockedText: string,
  memText: string,
  now: number,
): Snapshot => {
  const list = parseJson(listText)
  if (!Array.isArray(list)) {
    return {
      beads: [],
      memories: [],
      ready: [],
      blocked: {},
      at: now,
      error: 'bd list gave no JSON array',
    }
  }
  const beads = list.flatMap(r => {
    const b = toBead(r as Record<string, unknown>)
    return b === null ? [] : [b]
  })
  const readyRaw = parseJson(readyText)
  const ready = (Array.isArray(readyRaw) ? readyRaw : []).flatMap(r => {
    const id = asText((r as Record<string, unknown>).id)
    return id === null ? [] : [id]
  })
  const blockedRaw = parseJson(blockedText)
  const blocked: Record<string, string[]> = {}
  for (const r of Array.isArray(blockedRaw) ? blockedRaw : []) {
    const rec = r as Record<string, unknown>
    const id = asText(rec.id)
    if (id !== null) {
      blocked[id] = (Array.isArray(rec.blocked_by) ? rec.blocked_by : []).filter(
        (x): x is string => typeof x === 'string',
      )
    }
  }

  return { beads, memories: parseMemories(memText), ready, blocked, at: now, error: null }
}

export const stateOf = (snap: Snapshot, b: Bead): State => {
  if (b.status === 'closed') return 'closed'
  if (b.status === 'in_progress') return 'in_progress'
  if (b.id in snap.blocked || b.status === 'blocked') return 'blocked'
  if (snap.ready.includes(b.id)) return 'ready'
  return 'waiting'
}

export const summary = (snap: Snapshot): string => {
  const counts = { ready: 0, in_progress: 0, blocked: 0 }
  for (const b of snap.beads) {
    const s = stateOf(snap, b)
    if (s === 'ready' || s === 'in_progress' || s === 'blocked') counts[s] += 1
  }

  return `beads: ${counts.ready} ready · ${counts.in_progress} wip · ${counts.blocked} blocked`
}

const byId = (snap: Snapshot): Map<string, Bead> => new Map(snap.beads.map(b => [b.id, b]))

const blockersOf = (b: Bead): string[] =>
  b.deps.filter(d => BLOCKING.includes(d.type)).map(d => d.to)

const text = (r: Row): string => r.parts.map(p => p.t).join('')

export const clip = (parts: Part[], width: number): Part[] => {
  const out: Part[] = []
  let left = Math.max(4, width)
  for (const p of parts) {
    if (p.t.length <= left) {
      out.push(p)
      left -= p.t.length
    } else {
      out.push({ ...p, t: `${p.t.slice(0, Math.max(0, left - 1))}…` })
      return out
    }
  }

  return out
}

const prio = (b: Bead): Part => ({
  t: `P${b.priority} `,
  tone: b.priority === 0 ? 'bad' : b.priority === 1 ? 'warn' : 'dim',
})

const kind = (b: Bead): Part[] => (b.type === 'task' ? [] : [{ t: `${b.type} `, tone: 'dim' }])

const beadRow = (
  snap: Snapshot,
  b: Bead,
  width: number,
  opts: { prefix?: string; extra?: Part[]; idLast?: boolean } = {},
): Row => {
  const s = stateOf(snap, b)
  const head: Part[] = [
    ...(opts.prefix ? [{ t: opts.prefix, tone: 'dim' as const }] : []),
    { t: `${ICON[s]} `, tone: TONE[s] },
  ]
  const id: Part = { t: opts.idLast ? ` ${b.id}` : `${b.id} `, tone: 'dim' }
  const body: Part[] = [prio(b), ...kind(b), { t: b.title, tone: s === 'closed' ? 'dim' : 'plain' }]
  const parts = opts.idLast
    ? [...head, ...body, id, ...(opts.extra ?? [])]
    : [...head, id, ...body, ...(opts.extra ?? [])]

  return { id: b.id, parts: clip(parts, width) }
}

const order = (a: Bead, b: Bead): number =>
  a.priority - b.priority || (a.createdAt ?? '').localeCompare(b.createdAt ?? '') || a.id.localeCompare(b.id)

const unblocks = (snap: Snapshot): Map<string, number> => {
  const n = new Map<string, number>()
  for (const b of snap.beads) {
    if (b.status === 'closed') continue
    for (const to of blockersOf(b)) n.set(to, (n.get(to) ?? 0) + 1)
  }

  return n
}

export const viewBoard = (snap: Snapshot, width: number): ViewOut => {
  const cols: { title: string; tone: Tone; keep: (s: State) => boolean }[] = [
    { title: 'Ready', tone: 'ok', keep: s => s === 'ready' },
    { title: 'In progress', tone: 'accent', keep: s => s === 'in_progress' },
    { title: 'Blocked', tone: 'bad', keep: s => s === 'blocked' },
    { title: 'Waiting', tone: 'warn', keep: s => s === 'waiting' },
    { title: 'Done', tone: 'dim', keep: s => s === 'closed' },
  ]
  const used = cols.filter(
    c => c.title !== 'Waiting' || snap.beads.some(b => c.keep(stateOf(snap, b))),
  )
  const isColumns = width >= 90
  const colWidth = isColumns ? Math.floor((width - (used.length - 1) * 2) / used.length) : width
  const sections = used.map(c => {
    const all = snap.beads.filter(b => c.keep(stateOf(snap, b)))
    const sorted =
      c.title === 'Done'
        ? [...all].sort((a, b) => (b.updatedAt ?? '').localeCompare(a.updatedAt ?? ''))
        : [...all].sort(order)
    const shown = c.title === 'Done' ? sorted.slice(0, DONE_LIMIT) : sorted
    const rows = shown.map(b => beadRow(snap, b, colWidth, { idLast: isColumns }))
    if (shown.length < all.length) {
      rows.push({ parts: [{ t: `… ${all.length - shown.length} more`, tone: 'dim' }] })
    }

    return { title: `${c.title} (${all.length})`, tone: c.tone, rows }
  })

  return { layout: isColumns ? 'columns' : 'stack', sections }
}

export const viewReady = (snap: Snapshot, width: number): ViewOut => {
  const gain = unblocks(snap)
  const lookup = byId(snap)
  const ready = snap.beads
    .filter(b => stateOf(snap, b) === 'ready')
    .sort((a, b) => a.priority - b.priority || (gain.get(b.id) ?? 0) - (gain.get(a.id) ?? 0) || order(a, b))
  const rows = ready.map(b => {
    const n = gain.get(b.id) ?? 0
    const extra: Part[] = n > 0 ? [{ t: `  unblocks ${n}`, tone: 'accent' }] : []
    const parent = b.parent === null ? undefined : lookup.get(b.parent)
    if (parent !== undefined) extra.push({ t: `  in ${parent.id}`, tone: 'dim' })

    return beadRow(snap, b, width, { extra })
  })

  return {
    layout: 'stack',
    sections: [{ title: `Ready frontier (${ready.length})`, tone: 'ok', rows }],
    note: 'Open, no open blockers. Ranked by priority, then by how much each unblocks. Claim: bd update <id> --claim',
  }
}

export const viewGraph = (snap: Snapshot, width: number, showClosed: boolean): ViewOut => {
  const lookup = byId(snap)
  const alive = (b: Bead): boolean => showClosed || b.status !== 'closed'
  const live = new Set(snap.beads.filter(alive).map(b => b.id))
  const connected = new Set<string>()
  for (const b of snap.beads) {
    if (!live.has(b.id)) continue
    for (const to of blockersOf(b)) {
      if (live.has(to)) {
        connected.add(b.id)
        connected.add(to)
      }
    }
  }
  const layer = new Map<string, number>()
  const walking = new Set<string>()
  const depth = (id: string): number => {
    const known = layer.get(id)
    if (known !== undefined) return known
    if (walking.has(id)) return 0
    walking.add(id)
    const b = lookup.get(id)
    const above = (b === undefined ? [] : blockersOf(b)).filter(x => connected.has(x))
    const n = above.length === 0 ? 0 : 1 + Math.max(...above.map(depth))
    walking.delete(id)
    layer.set(id, n)

    return n
  }
  const nodes = snap.beads.filter(b => connected.has(b.id))
  for (const b of nodes) depth(b.id)
  const top = nodes.reduce((m, b) => Math.max(m, layer.get(b.id) ?? 0), 0)
  const sections: Section[] = []
  for (let i = 0; i <= top && nodes.length > 0; i += 1) {
    const here = nodes.filter(b => layer.get(b.id) === i).sort(order)
    const rows = here.map(b => {
      const from = blockersOf(b).filter(x => connected.has(x))
      const extra: Part[] = from.length > 0 ? [{ t: `  ← ${from.join(', ')}`, tone: 'dim' }] : []

      return beadRow(snap, b, width, { extra })
    })
    sections.push({
      title: i === 0 ? 'Layer 0 · no blockers, start here' : `Layer ${i} · after layer ${i - 1}`,
      tone: i === 0 ? 'ok' : 'plain',
      rows,
    })
  }
  const loose = snap.beads.filter(b => alive(b) && !connected.has(b.id)).length

  return {
    layout: 'stack',
    sections,
    note:
      nodes.length === 0
        ? 'No blocking dependencies yet. Add one: bd dep add <blocked> <blocker>'
        : `${loose} bead${loose === 1 ? '' : 's'} with no blocking edges not shown.`,
  }
}

const bar = (done: number, total: number, cells = 8): string => {
  const full = total === 0 ? 0 : Math.round((done / total) * cells)

  return `${'█'.repeat(full)}${'░'.repeat(cells - full)}`
}

export const viewTree = (snap: Snapshot, width: number, showClosed: boolean): ViewOut => {
  const lookup = byId(snap)
  const kids = new Map<string, Bead[]>()
  const roots: Bead[] = []
  for (const b of snap.beads) {
    if (b.parent !== null && lookup.has(b.parent)) {
      kids.set(b.parent, [...(kids.get(b.parent) ?? []), b])
    } else {
      roots.push(b)
    }
  }
  const below = (id: string, seen = new Set<string>()): Bead[] => {
    if (seen.has(id)) return []
    seen.add(id)

    return (kids.get(id) ?? []).flatMap(k => [k, ...below(k.id, seen)])
  }
  const rows: Row[] = []
  const walk = (b: Bead, prefix: string, isLast: boolean, isRoot: boolean, seen: Set<string>): void => {
    if (seen.has(b.id)) return
    seen.add(b.id)
    const all = below(b.id)
    const done = all.filter(x => x.status === 'closed').length
    const extra: Part[] =
      all.length > 0 ? [{ t: `  [${bar(done, all.length)}] ${done}/${all.length}`, tone: 'accent' }] : []
    const lead = isRoot ? '' : `${prefix}${isLast ? '└─ ' : '├─ '}`
    rows.push(beadRow(snap, b, width, { prefix: lead, extra }))
    const shown = (kids.get(b.id) ?? []).filter(k => showClosed || k.status !== 'closed').sort(order)
    const next = isRoot ? '' : `${prefix}${isLast ? '   ' : '│  '}`
    shown.forEach((k, i) => walk(k, next, i === shown.length - 1, false, seen))
  }
  const seen = new Set<string>()
  const parents = roots.filter(r => (kids.get(r.id) ?? []).length > 0).sort(order)
  for (const r of parents) walk(r, '', true, true, seen)
  const loneAll = roots.filter(r => !(kids.get(r.id) ?? []).length)
  const lone = loneAll.filter(r => showClosed || r.status !== 'closed').sort(order)
  const sections: Section[] = []
  if (rows.length > 0) sections.push({ title: `Hierarchy (${parents.length})`, tone: 'head', rows })
  if (lone.length > 0) {
    sections.push({
      title: `No parent or children (${lone.length})`,
      tone: 'dim',
      rows: lone.map(b => beadRow(snap, b, width)),
    })
  }

  return {
    layout: 'stack',
    sections,
    note: parents.length === 0 ? 'No epics yet. Group work: bd create "..." --parent <epic>' : undefined,
  }
}

const count = <T>(items: T[], key: (x: T) => string): [string, number][] => {
  const m = new Map<string, number>()
  for (const x of items) m.set(key(x), (m.get(key(x)) ?? 0) + 1)

  return [...m.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
}

export const viewStats = (snap: Snapshot, width: number): ViewOut => {
  const total = snap.beads.length
  const states = count(snap.beads, b => stateOf(snap, b))
  const max = Math.max(1, ...states.map(s => s[1]))
  const line = (label: string, n: number, tone: Tone, of = max): Row => ({
    parts: [
      { t: label.padEnd(13), tone: 'plain' },
      { t: bar(n, of, 20), tone },
      { t: ` ${n}`, tone: 'dim' },
    ],
  })
  const label: Record<string, string> = {
    ready: 'ready',
    in_progress: 'in progress',
    blocked: 'blocked',
    waiting: 'waiting',
    closed: 'closed',
  }
  const stateRows = (['ready', 'in_progress', 'blocked', 'waiting', 'closed'] as State[])
    .map(s => [s, states.find(x => x[0] === s)?.[1] ?? 0] as const)
    .filter(([, n]) => n > 0)
    .map(([s, n]) => line(label[s] ?? s, n, TONE[s]))
  const types = count(snap.beads, b => b.type)
  const prios = count(snap.beads, b => `P${b.priority}`).sort((a, b) => a[0].localeCompare(b[0]))
  const epics = snap.beads.filter(b => b.type === 'epic' && b.status !== 'closed')
  const progress = epics.map(e => {
    const subs = snap.beads.filter(b => b.parent === e.id)
    const done = subs.filter(b => b.status === 'closed').length

    return {
      parts: clip(
        [
          { t: `${bar(done, subs.length)} `, tone: 'accent' as const },
          { t: `${done}/${subs.length} `, tone: 'dim' as const },
          { t: e.title },
        ],
        width,
      ),
    }
  })
  const wip = snap.beads
    .filter(b => b.status === 'in_progress')
    .sort((a, b) => (a.updatedAt ?? '').localeCompare(b.updatedAt ?? ''))
    .slice(0, 5)
    .map(b => {
      const age = b.updatedAt === null ? 0 : Math.floor((snap.at - Date.parse(b.updatedAt)) / DAY)
      const idle: Part[] = [{ t: `  idle ${Math.max(0, age)}d`, tone: age >= 3 ? 'warn' : 'dim' }]

      return beadRow(snap, b, width, { extra: idle })
    })
  const sections: Section[] = [
    { title: `Beads (${total})`, tone: 'head', rows: stateRows },
    { title: 'By type', tone: 'head', rows: types.map(([k, n]) => line(k, n, 'plain', total)) },
    { title: 'By priority', tone: 'head', rows: prios.map(([k, n]) => line(k, n, 'plain', total)) },
  ]
  if (progress.length > 0) sections.push({ title: 'Open epics', tone: 'head', rows: progress })
  if (wip.length > 0) sections.push({ title: 'Longest in progress', tone: 'head', rows: wip })

  return { layout: 'stack', sections }
}

export const detail = (snap: Snapshot, id: string, width: number): Row[] => {
  const lookup = byId(snap)
  const b = lookup.get(id)
  if (b === undefined) return []
  const s = stateOf(snap, b)
  const rows: Row[] = [
    {
      parts: clip(
        [
          { t: `${ICON[s]} `, tone: TONE[s] },
          { t: `${b.id} `, tone: 'head' },
          { t: `${s.replace('_', ' ')} · P${b.priority} · ${b.type}`, tone: 'dim' },
          ...(b.assignee === null ? [] : [{ t: ` · ${b.assignee}`, tone: 'dim' as const }]),
        ],
        width,
      ),
    },
    { parts: clip([{ t: b.title, tone: 'head' }], width) },
  ]
  const link = (label: string, other: Bead): Row => ({
    id: other.id,
    parts: clip(
      [
        { t: `${label} `, tone: 'dim' },
        { t: `${ICON[stateOf(snap, other)]} ${other.id} `, tone: TONE[stateOf(snap, other)] },
        { t: other.title },
      ],
      width,
    ),
  })
  if (b.parent !== null) {
    const p = lookup.get(b.parent)
    if (p !== undefined) rows.push(link('parent    ', p))
  }
  for (const to of blockersOf(b)) {
    const o = lookup.get(to)
    if (o !== undefined) rows.push(link('blocked by', o))
  }
  for (const o of snap.beads.filter(x => blockersOf(x).includes(b.id))) rows.push(link('blocks    ', o))
  const lines = (b.description ?? '').split('\n').filter(l => l.trim() !== '')
  for (const l of lines.slice(0, 5)) rows.push({ parts: clip([{ t: l, tone: 'dim' }], width) })
  if (lines.length > 5) rows.push({ parts: [{ t: `… ${lines.length - 5} more lines (bd show ${b.id})`, tone: 'dim' }] })

  return rows
}

export const plain = (out: ViewOut): string[] =>
  out.sections.flatMap(s => [s.title, ...s.rows.map(text)])

// beadmod-93m
export const FILTERS: Filter[] = ['all', 'ready', 'in_progress', 'blocked', 'waiting']

export const viewIssues = (
  snap: Snapshot,
  width: number,
  showClosed: boolean,
  filter: Filter,
): ViewOut => {
  const shown = snap.beads
    .filter(b => (filter === 'all' ? showClosed || b.status !== 'closed' : stateOf(snap, b) === filter))
    .sort(order)
  const rows = shown.map(b => {
    const extra: Part[] = b.assignee === null ? [] : [{ t: `  @${b.assignee}`, tone: 'dim' }]

    return beadRow(snap, b, width, { extra })
  })
  const label = filter === 'all' ? 'all' : filter.replace('_', ' ')

  return {
    layout: 'stack',
    sections: [{ title: `Issues (${shown.length}) · ${label}`, tone: 'head', rows }],
    note: 'l cycles the filter: all, ready, in progress, blocked, waiting.',
  }
}

const pad2 = (n: number): string => String(n).padStart(2, '0')
const hhmm = (ms: number): string => `${pad2(new Date(ms).getHours())}:${pad2(new Date(ms).getMinutes())}`
const dayOf = (ms: number): string => {
  const d = new Date(ms)

  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`
}

type Event = { ms: number; verb: string; tone: Tone; bead: Bead }

export const viewActivity = (snap: Snapshot, width: number): ViewOut => {
  const events: Event[] = []
  for (const b of snap.beads) {
    const made = Date.parse(b.createdAt ?? '')
    const touched = Date.parse(b.updatedAt ?? '')
    const closed = Date.parse(b.closedAt ?? b.updatedAt ?? '')
    if (!Number.isNaN(made)) events.push({ ms: made, verb: 'created', tone: 'accent', bead: b })
    if (b.status === 'closed' && !Number.isNaN(closed)) {
      events.push({ ms: closed, verb: 'closed', tone: 'ok', bead: b })
    } else if (!Number.isNaN(touched) && (Number.isNaN(made) || touched - made > 2000)) {
      const started = b.status === 'in_progress'
      events.push({
        ms: touched,
        verb: started ? 'started' : 'updated',
        tone: started ? 'warn' : 'dim',
        bead: b,
      })
    }
  }
  events.sort((a, b) => b.ms - a.ms || a.bead.id.localeCompare(b.bead.id))
  const today = dayOf(snap.at)
  const yesterday = dayOf(snap.at - DAY)
  const sections: Section[] = []
  for (const ev of events.slice(0, 80)) {
    const day = dayOf(ev.ms)
    const title = day === today ? 'Today' : day === yesterday ? 'Yesterday' : day
    let sec = sections[sections.length - 1]
    if (sec === undefined || sec.title !== title) {
      sec = { title, tone: 'head', rows: [] }
      sections.push(sec)
    }
    sec.rows.push({
      id: ev.bead.id,
      parts: clip(
        [
          { t: `${hhmm(ev.ms)} `, tone: 'dim' },
          { t: ev.verb.padEnd(8), tone: ev.tone },
          { t: `${ev.bead.id} `, tone: 'dim' },
          { t: ev.bead.title, tone: ev.bead.status === 'closed' ? 'dim' : 'plain' },
        ],
        width,
      ),
    })
  }

  return {
    layout: 'stack',
    sections,
    note: 'Built from bead timestamps: created, started, updated and closed.',
  }
}

export const viewMemory = (snap: Snapshot, width: number): ViewOut => {
  const rows = snap.memories.flatMap(m => {
    const room = Math.max(10, width - 2)
    const chunks: string[] = []
    for (let i = 0; i < m.text.length && chunks.length < 4; i += room) chunks.push(m.text.slice(i, i + room))
    if (chunks.length === 4 && m.text.length > room * 4) chunks[3] = `${chunks[3]?.slice(0, room - 1)}…`

    return [
      { parts: [{ t: m.key, tone: 'accent' as const }] },
      ...chunks.map(c => ({ parts: [{ t: `  ${c}`, tone: 'plain' as const }] })),
    ]
  })

  return {
    layout: 'stack',
    sections: [{ title: `Memories (${snap.memories.length})`, tone: 'head', rows }],
    note: snap.memories.length === 0 ? 'Nothing remembered yet.' : undefined,
  }
}

